&reftitle.parameters;




   result

    &pgsql.parameter.result;



   row



     Numero della riga nel risultato. Le righe sono numerate a partire da 0. Se omesso,
     viene recuperata la riga corrente.

&reftitle.changelog;





    &Version;
    &Description;





    8.4.0

     La firma a due argomenti di
     pg_field_prtlen
     (result,
     field_name_or_number) è ora deprecata.
     Utilizzare invece la firma a tre argomenti con
     row impostato a &null;.




    8.3.0

     row ora è nullable.


   &pgsql.changelog.result-object;

  &reftitle.examples;



    Ottenere informazioni sui campi


<?php
  $dbconn = pg_connect("dbname=publisher") or die("Impossibile connettersi");

  $res = pg_query($dbconn, "select * from authors where author = 'Orwell'");
  $i = pg_num_fields($res);
  for ($j = 0; $j < $i; $j++) {
      echo "colonna $j\n";
      $fieldname = pg_field_name($res, $j);
      echo "nome del campo: $fieldname\n";
      echo "lunghezza stampata: " . pg_field_prtlen($res, $fieldname) . " caratteri\n";
      echo "lunghezza di memorizzazione: " . pg_field_size($res, $j) . " byte\n";
      echo "tipo del campo: " . pg_field_type($res, $j) . " \n\n";
  }
?>


    &example.outputs;


colonna 0
nome del campo: author
lunghezza stampata: 6 caratteri
lunghezza di memorizzazione: -1 byte
tipo del campo: varchar 

colonna 1
nome del campo: year
lunghezza stampata: 4 caratteri
lunghezza di memorizzazione: 2 byte
tipo del campo: int2 

colonna 2
nome del campo: title
lunghezza stampata: 24 caratteri
lunghezza di memorizzazione: -1 byte
tipo del campo: varchar
